logia celular","DIFICULTAD":"facil","PREGUNTA":"¿Qué componente gramnegativo puede actuar como endotoxina?","OPCION_A":"El lipopolisacárido de la membrana externa.","OPCION_B":"Los poxvirus, como el de la viruela.","OPCION_C":"Una membrana externa que contiene lipopolisacáridos.","OPCION_D":"La enfermedad de Creutzfeldt-Jakob.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El lipopolisacárido de la membrana externa.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"34–52"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"facil","PREGUNTA":"¿Qué efectos puede desencadenar el lipopolisacárido al activar la respuesta del huésped?","OPCION_A":"Fiebre y señales de inflamación, entre otros.","OPCION_B":"Células de epitelio escamoso de piel o mucosas.","OPCION_C":"Encefalopatías espongiformes transmisibles.","OPCION_D":"Filamentos formados por células alargadas.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Fiebre y señales de inflamación, entre otros.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"34–52"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"facil","PREGUNTA":"¿Qué ventaja puede aportar una cápsula bacteriana?","OPCION_A":"Resistencia a antibióticos o adaptación a ciertas condiciones.","OPCION_B":"Entre otros, células sanguíneas, protozoos, espermatozoides y bacterias.","OPCION_C":"Puede inducir un cambio de forma que convierte a la normal en patógena.","OPCION_D":"Protección frente a desecación y fagocitosis, además de facilitar la adhesión.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Protección frente a desecación y fagocitosis, además de facilitar la adhesión.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"34–52"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"medio","PREGUNTA":"Si una bacteria tiene forma de esfera, ¿cómo se llama esa forma?","OPCION_A":"Bacilo.","OPCION_B":"Coco.","OPCION_C":"Espirilo.","OPCION_D":"A la eucariota.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Coco.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"34–52"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"medio","PREGUNTA":"Si una bacteria tiene forma de bastón, ¿cómo se llama esa forma?","OPCION_A":"Coco.","OPCION_B":"Espirilo.","OPCION_C":"Bacilo.","OPCION_D":"A la eucariota.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Bacilo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"34–52"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"medio","PREGUNTA":"Si una bacteria tiene forma espiral, ¿qué término utiliza el capítulo?","OPCION_A":"Bacilo.","OPCION_B":"Espirilo.","OPCION_C":"Coco.","OPCION_D":"A la eucariota.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Espirilo.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"34–52"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"medio","PREGUNTA":"¿Dónde se encuentran las enzimas y los ribosomas bacterianos si no hay núcleo?","OPCION_A":"Hemaglutinina y neuraminidasa.","OPCION_B":"ADN circular de doble cadena.","OPCION_C":"Mycobacterium tuberculosis.","OPCION_D":"Distribuidos en el citoplasma.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Distribuidos en el citoplasma.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"34–52"},{"MATERIA":"BIOLOGIA CELULAR","TEMA":"introduccion a la biologia celular","DIFICULTAD":"facil","PREGUNTA":"¿Qué es un plásmido bacteriano?","OPCION_A":"Una pequeña molécula circular de ADN fuera del cromosoma principal.","OPCION_B":"La posibilidad de observar estructuras internas con mucho más detalle.","OPCION_C":"Una proteína mal plegada capaz de inducir el mal plegamiento de otras.","OPCION_D":"El viroide es ARN circular pequeño sin cubierta proteica.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Una pequeña molécula circular de ADN fuera del cromosoma principal.","FUENTE":"Biología celular y biomédica, St. Alfonso","PAGINAS_PDF":"34–52"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;
